#include "semantics/validate.hpp"
#include <set>
namespace bridgeabi::generator {
const char* ownership_name(ownership value) noexcept { switch (value) { case ownership::borrowed: return "borrowed"; case ownership::owned: return "owned"; case ownership::transferred: return "transferred"; case ownership::shared: return "shared"; case ownership::static_lifetime: return "static"; case ownership::host_owned: return "host_owned"; case ownership::plugin_owned: return "plugin_owned"; default: return ""; } }
bool validate(interface_definition& d, std::string& error) noexcept { try { if (d.id.empty()) { error = "BRG1001: Missing interface identity (@id)"; return false; } if (d.major == 0) { error = "BRG1003: Interface major version must be non-zero"; return false; } std::set<std::uint32_t> ids; for (auto& method : d.methods) { if (method.id == 0) method.id = static_cast<std::uint32_t>(&method - d.methods.data() + 1); if (!ids.insert(method.id).second) { error = "BRG1201: Duplicate method identifier"; return false; } for (const auto& p : method.parameters) { if ((p.type == "string" || p.type == "buffer") && p.owner == ownership::none) { error = "BRG1101: Ambiguous ownership for parameter '" + p.name + "'"; return false; } if (p.nullable && p.type != "string" && p.type != "buffer" && p.type.rfind("handle", 0) != 0) { error = "BRG1102: Nullable value type '" + p.type + "'"; return false; } } if ((method.result_type == "string" || method.result_type == "buffer") && method.result_owner == ownership::none) { error = "BRG1101: Ambiguous ownership for return value of '" + method.name + "'"; return false; } } return true; } catch (...) { error = "BRG9999: Semantic analysis ran out of memory"; return false; } }
}
